"""Review front quads, source-derived raised lights and clipped icosphere caps."""
import html,json,sys
from pathlib import Path


def main():
    out=Path(sys.argv[1]).resolve();r=json.loads((out/'summary.json').read_bytes());v=json.loads((out/'validation.json').read_bytes());stages={'ico2':'Recommended · 90-triangle optic','strips':'Strip quads only','ico1':'Coarse optic · rejected'};scopes={'whole':('Whole Base','e15-a60'),'rear':('Whole Base · reverse','e15-a180'),'top':('Top view','top'),'cover':('Long strip','unit-4392221'),'cover-rear':('Long strip · reverse','unit-4392221-rear'),'module':('Armor-module lights','unit-4099408'),'module-rear':('Armor-module lights · reverse','unit-4099408-rear'),'small':('Small module','unit-4561335'),'optic':('Green optic · front','optic-front'),'optic-wire':('Green optic · wireframe','optic-front-wire'),'optic-side':('Green optic · oblique','optic-side'),'optic-rear':('Green optic · rear','optic-rear')};panels=[]
    for stage,label in stages.items():
        for scope,(name,suffix) in scopes.items():
            panels.append(f'<section class="comparison" data-stage="{stage}" data-scope="{scope}" '+('' if stage=='ico2' and scope=='whole' else 'hidden')+'><div class="pair">'+''.join(f'<figure><figcaption>{title}</figcaption><img src="{html.escape(str(out/(key+"-"+suffix+".png")))}" alt="{html.escape(name+": "+title)}"></figure>' for key,title in [('before','Approved baseline'),(stage,label)])+'</div></section>')
    stage_opts=''.join(f'<option value="{s}">{label}</option>' for s,label in stages.items());scope_opts=''.join(f'<option value="{s}">{name}</option>' for s,(name,_) in scopes.items());rows=[]
    for label,before,after in [('Long cover strips',2522,6),('Raised module lights',3552,1454),('Small red source parts',1560,1272),('Green optic',326,90),('All red/green light surfaces',7960,2822)]:rows.append(f'<tr><td>{label}</td><td>{before:,}</td><td>{after:,}</td></tr>')
    whole=[x for x in v['stages']['ico2'] if x['source_unit_id'] is None];max_rgb=max(x['rgb_changed_over_10_fraction'] for x in whole)*100
    page='''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>
body{margin:0;font:14px/1.5 var(--font-sans,system-ui);color:var(--foreground,#17202f)}h3{font-size:17px;margin:15px 0 8px}p{margin:8px 0}.stats{display:flex;gap:24px;flex-wrap:wrap}.stats b{display:block;font-size:24px}.note{font-size:12px;color:var(--muted-foreground,#667085)}nav{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0}select,button{font:inherit;padding:7px;border:1px solid var(--border,#aaa);border-radius:6px;background:var(--background,white);color:inherit;cursor:pointer;max-width:100%}.pair{display:grid;grid-template-columns:1fr 1fr;gap:10px}figure{margin:0}figcaption{font-size:12px;margin:5px 0}img{width:100%;display:block;border-radius:var(--radius,6px)}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}td,th{padding:6px 0;border-bottom:1px solid var(--border,#ddd);text-align:right}td:first-child,th:first-child{text-align:left}body[data-mode=before] figure:nth-child(2),body[data-mode=after] figure:first-child{display:none}body[data-mode=before] .pair,body[data-mode=after] .pair{grid-template-columns:1fr}[hidden]{display:none!important}@media(max-width:430px){.pair{grid-template-columns:1fr}table{font-size:12px}}
</style></head><body><div class="stats"><div><b>2 triangles</b>per long strip</div><div><b>90 triangles</b>green icosphere cap</div><div><b>64.5%</b>less light geometry</div></div><p class="note">Approved passes committed as 16a2a86. These subsequent light candidates are uncommitted. Original CAD, runtime assets and the approved collider remain unchanged.</p><nav><select id="stage" aria-label="Candidate" onchange="update()">'''+stage_opts+'''</select><select id="scope" aria-label="Part and view" onchange="update()">'''+scope_opts+'''</select></nav><nav><button onclick="document.body.dataset.mode='both'">Both</button><button onclick="document.body.dataset.mode='before'">Approved</button><button onclick="document.body.dataset.mode='after'">Candidate</button></nav>'''+''.join(panels)+f'''<p class="note">In-situ views retain surrounding opaque geometry. The green optic uses smooth radial normals in both the export and diagnostic renderer. This is a diffuse diagnostic, not the runtime PBR renderer.</p><h3>What became simpler</h3><table><tr><th>Triangles per Base</th><th>Approved</th><th>Recommended</th></tr>'''+''.join(rows)+f'''</table><p>Total visual: <b>142,120 → 136,982 triangles per Base</b>. All 134,160 non-light triangles remain byte-exact. Collision stays at 16,857 triangles. Two placed Bases reuse the same definition.</p><h3>Hidden overlap and exposed surfaces</h3><p>Overlapping an opaque housing is acceptable for a visual light surface when the extra area stays hidden. Coplanar overlap can flicker. Collision should keep its own surface; overlapping collision meshes can create redundant contacts, and visible protrusions change contact geometry.</p><p>The three long strips use their exact source front rectangles. Raised module lights retain source-derived contours and side surfaces: one quad lost oblique light, independent plane covers left seams, and enclosing boxes produced red protrusions beyond bezels and through rear gaps. Those replacements were rejected. The smaller source-derived models keep their finite material borders, with a 0.5 mm sampled-distance guard.</p><h3>The green light is a spherical cap</h3><p>Its source vertices fit a <b>40 mm radius sphere</b> with less than 0.00001 mm residual. A level-2 icosphere is clipped 1 mm behind the source aperture, leaving 90 triangles. Its full rear is absent, so there is no green ball extending through the back of the housing.</p><p>The front close-up changes only 10 green foreground pixels out of 569,481; the oblique close-up changes 1.15%. The 34-triangle alternative loses 8.55% of front green area and is rejected. Rear checks show no new green pixels.</p><p class="note">18 whole-assembly views and 11 close-ups checked. Worst whole-image RGB change above 10/255: {max_rgb:.4f}%. These source-pose samples do not prove every moving pose or complete occlusion. Source colors and emission settings remain unchanged.</p><p class="note">300 tests run: 299 passed, one optional skip. Independent checks cover every non-light triangle and source-unit palette, plus the exported green radial normals. No new light geometry is used as a collider.</p><script>function update(){{const s=document.getElementById('stage').value,v=document.getElementById('scope').value;document.querySelectorAll('.comparison').forEach(p=>p.hidden=p.dataset.stage!==s||p.dataset.scope!==v)}}update();console.assert(document.querySelectorAll('.comparison').length===36);console.log('Three candidates × twelve scopes; recommended and rejected coarse optic ready.');</script></body></html>'''
    (out/'review.html').write_text(page);print(out/'review.html')


if __name__=='__main__':main()
